/**
 * `node scripts/litestream-notices.mjs <out> <go version -m output>...` — writes the notices of
 * everything compiled into the pinned Litestream binary (`deploy/Dockerfile`, the `litestream`
 * stage) with `scripts/go-binary-notices.mjs`. The committed notice's `Generated by:` line names
 * this command, so it is kept to regenerate that file unchanged.
 */
import { isMainScript } from "./is-main-script.mjs";
import * as goBinary from "./go-binary-notices.mjs";

export {
  NOTICE_NAME,
  escapeModulePath,
  noticeFiles,
  parseBuildInfo,
  readZip,
} from "./go-binary-notices.mjs";

const NAME = "Litestream";
const COMMAND = "node scripts/litestream-notices.mjs <out> <go version -m output>...";

/**
 * @param {Omit<Parameters<typeof goBinary.renderNotices>[0], "name" | "version" | "command"> & { litestream: string }} input
 */
export function renderNotices({ litestream, ...rest }) {
  return goBinary.renderNotices({ ...rest, name: NAME, version: litestream, command: COMMAND });
}

/** @param {Omit<Parameters<typeof goBinary.generate>[0], "name" | "version" | "command">} options */
export function generate(options) {
  return goBinary.generate({ ...options, name: NAME, command: COMMAND });
}

/**
 * @param {string[]} argv
 * @param {Parameters<typeof goBinary.main>[1]} io
 * @returns {Promise<number>} the exit status
 */
export async function main(argv, { stdout, stderr, fetch }) {
  const [out, ...inputs] = argv;
  if (out === undefined || inputs.length === 0) {
    stderr(`usage: ${COMMAND}`);
    return 2;
  }
  await goBinary.writeNotices(out, inputs, { name: NAME, command: COMMAND }, { stdout, fetch });
  return 0;
}

/* v8 ignore start */
if (isMainScript(import.meta.url)) {
  process.exitCode = await main(process.argv.slice(2), {
    stdout: console.log,
    stderr: console.error,
  });
}
/* v8 ignore stop */
